using System.Text.RegularExpressions;

namespace Codex.Domain.Apps;

/// <summary>
/// Validates and extracts a single SVG path — the "d" data of an owner-created shelf's engraved
/// bookend glyph, generated by Claude (feature #11). Kept pure so the model reply is checked
/// without a device and the head only ever renders a path it has already validated; anything that
/// doesn't look like a lone monochrome path is rejected and the caller falls back to the monogram.
/// The path is authored in a 0–100 viewBox by convention (the renderer scales it to the bookend).
/// </summary>
public static partial class GlyphPath
{
    private const int MaxLength = 4000;

    [GeneratedRegex(@"^[MmLlHhVvCcSsQqTtAaZz0-9.,\-+eE\s]+$")]
    private static partial Regex AllowedChars();

    [GeneratedRegex(@"[Mm][MmLlHhVvCcSsQqTtAaZz0-9.,\-+eE\s]*")]
    private static partial Regex PathRun();

    [GeneratedRegex(@"[LlHhVvCcSsQqTtAaZz]")]
    private static partial Regex DrawCommand();

    /// <summary>True when the string is a plausible single SVG path: it starts with a move, uses
    /// only path syntax, actually draws something (more than a bare move), and isn't absurdly long.</summary>
    public static bool IsValid(string? path)
    {
        if (string.IsNullOrWhiteSpace(path))
        {
            return false;
        }
        var trimmed = path.Trim();
        if (trimmed.Length > MaxLength)
        {
            return false;
        }
        var first = trimmed[0];
        return (first == 'M' || first == 'm')
            && AllowedChars().IsMatch(trimmed)
            && DrawCommand().IsMatch(trimmed);
    }

    /// <summary>
    /// Pulls a valid path out of a model reply that may be wrapped in code fences or prose. Returns
    /// the path string, or null when the reply contains nothing that validates.
    /// </summary>
    public static string? Extract(string? reply)
    {
        if (string.IsNullOrWhiteSpace(reply))
        {
            return null;
        }
        var cleaned = reply.Replace("`", " ").Trim();
        if (IsValid(cleaned))
        {
            return cleaned;
        }
        foreach (Match match in PathRun().Matches(cleaned))
        {
            var candidate = match.Value.Trim();
            if (IsValid(candidate))
            {
                return candidate;
            }
        }
        return null;
    }
}
